#include "protocol.h"
int cl_parse_request(const unsigned char*b,size_t n,uint32_t previous,struct cl_request*out){uint32_t id;if(!b||!out||n<8||n>CL_MAX_REQUEST||b[0]!=1||b[1]<1||b[1]>12||b[2]||b[3])return 0;id=(uint32_t)b[4]|((uint32_t)b[5]<<8)|((uint32_t)b[6]<<16)|((uint32_t)b[7]<<24);if(!id||id<=previous)return 0;out->opcode=b[1];out->id=id;out->body=b+8;out->bytes=n-8;return 1;}
struct scan{const unsigned char*b;size_t n,at;};
static void whitespace(struct scan*s){while(s->at<s->n&&(s->b[s->at]==' '||s->b[s->at]=='\t'||s->b[s->at]=='\r'||s->b[s->at]=='\n'))s->at++;}
static int literal(struct scan*s,const char*t){size_t i=0;while(t[i]){if(s->at+i>=s->n||s->b[s->at+i]!=(unsigned char)t[i])return 0;i++;}s->at+=i;return 1;}
static int string(struct scan*s,size_t*begin,size_t*end){unsigned c,j;if(s->at>=s->n||s->b[s->at++]!='"')return 0;*begin=s->at;while(s->at<s->n){c=s->b[s->at++];if(c=='"'){*end=s->at-1;return 1;}if(c<32)return 0;if(c=='\\'){if(s->at>=s->n)return 0;c=s->b[s->at++];if(c=='u'){for(j=0;j<4;j++){if(s->at>=s->n)return 0;c=s->b[s->at++];if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F')))return 0;}}else if(c!='"'&&c!='\\'&&c!='/'&&c!='b'&&c!='f'&&c!='n'&&c!='r'&&c!='t')return 0;}}return 0;}
static int span(const struct scan*s,size_t b,size_t e,const char*t){size_t i=0;while(t[i]){if(b+i>=e||s->b[b+i]!=(unsigned char)t[i])return 0;i++;}return b+i==e;}
static unsigned b64value(unsigned c){return c>='A'&&c<='Z'?c-'A':c>='a'&&c<='z'?c-'a'+26:c>='0'&&c<='9'?c-'0'+52:c=='+'?62:63;}
static int base64(const struct scan*s,size_t b,size_t e){size_t i,n=e-b,pad=0;if(n%4||n>87384)return 0;if(n&&s->b[e-1]=='=')pad++;if(n>1&&s->b[e-2]=='=')pad++;if(n/4*3-pad>65536)return 0;for(i=b;i<e-pad;i++){unsigned c=s->b[i];if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/'))return 0;}if(pad==2&&(b64value(s->b[e-pad-1])&15))return 0;if(pad==1&&(b64value(s->b[e-pad-1])&3))return 0;return 1;}
int cl_catalog_json(unsigned op,const unsigned char*b,size_t n,int ro){struct scan s;unsigned mask=0,field;size_t begin,end,action_begin=0,action_end=0;if((op!=1&&op!=2&&op!=7&&op!=9&&op!=12&&op!=13)||!b||!n||n>(op==9?131072:16384)||(ro&&(op==1||op==9||op==12)))return 0;s.b=b;s.n=n;s.at=0;whitespace(&s);if(!literal(&s,"{"))return 0;for(;;){whitespace(&s);if(!string(&s,&begin,&end))return 0;field=span(&s,begin,end,"action")?1:span(&s,begin,end,"path")?2:span(&s,begin,end,"principal")?4:span(&s,begin,end,"scope")?8:span(&s,begin,end,"bytes")?16:span(&s,begin,end,"directory")?32:span(&s,begin,end,"profileRoot")?64:span(&s,begin,end,"privateDirectory")?128:span(&s,begin,end,"privateParent")?256:0;if(!field||(mask&field))return 0;mask|=field;whitespace(&s);if(!literal(&s,":"))return 0;whitespace(&s);if(field==32||field==128||field==256){if(!literal(&s,"true")&&!literal(&s,"false"))return 0;}else{if(!string(&s,&begin,&end))return 0;if(field==16&&!base64(&s,begin,end))return 0;if(field!=16&&end-begin>4096)return 0;if(field==1){action_begin=begin;action_end=end;}}whitespace(&s);if(literal(&s,"}"))break;if(!literal(&s,","))return 0;}whitespace(&s);if(s.at!=n)return 0;if(op==13)return mask==1&&span(&s,action_begin,action_end,"registry-status");if(op==12)return mask==387&&(span(&s,action_begin,action_end,"inspect")||span(&s,action_begin,action_end,"create"));if(op==9)return mask==31&&span(&s,action_begin,action_end,"write");if(op==7)return mask==1&&span(&s,action_begin,action_end,"observe");if(op==1)return mask==34;if(span(&s,action_begin,action_end,"identity")||span(&s,action_begin,action_end,"registry-status"))return mask==1;if(span(&s,action_begin,action_end,"inspect"))return mask==47;if(ro)return 0;if(span(&s,action_begin,action_end,"initialize"))return mask==1||mask==65;if(span(&s,action_begin,action_end,"mkdir"))return mask==15;if(span(&s,action_begin,action_end,"write"))return mask==31;return 0;}

void cl_config_write_reset(struct cl_config_write*w){size_t i;volatile unsigned char*p=w->body;for(i=0;i<w->used;i++)p[i]=0;w->declared=w->used=0;}
int cl_config_write_step(struct cl_config_write*w,unsigned op,const unsigned char*b,size_t n,int readonly){size_t i;if(readonly){cl_config_write_reset(w);return 0;}if(op==9){uint32_t size;if(w->declared||n!=4)goto bad;size=(uint32_t)b[0]|((uint32_t)b[1]<<8)|((uint32_t)b[2]<<16)|((uint32_t)b[3]<<24);if(!size||size>sizeof(w->body))goto bad;cl_config_write_reset(w);w->declared=size;return 1;}if(!w->declared)goto bad;if(op==10){if(!n||n>w->declared-w->used)goto bad;for(i=0;i<n;i++)w->body[w->used++]=b[i];return 1;}if(op==11&&n==0&&w->used==w->declared&&cl_catalog_json(9,w->body,w->used,0))return 2;bad:cl_config_write_reset(w);return 0;}
